const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const W=480,H=270,T=20,MAP_W=44,MAP_H=36,MW=MAP_W*T,MH=MAP_H*T;
const keys=new Set();let last=0,toastTimer=0,walkPhase=0,stepData;
const defaultSteps=[
  {title:'The meadow & a wanderer',note:'Grassland, little hero, and a first quest.',status:'current'},
  {title:'A village to call home',note:'Hearths, neighbors, and somewhere to rest.',status:'next'},
  {title:'Paths beyond the hills',note:'New places, secrets, and things to find.',status:'next'},
  {title:'A story of your own',note:'Shape the adventure together, one idea at a time.',status:'next'}
];
const state={x:430,y:355,face:'down',petals:[],wellDone:false,elapsed:0};
const keySave='fernhollow-save-v1',roadmapSave='fernhollow-roadmap-v1';
const flowers=[{x:358,y:278},{x:540,y:300},{x:625,y:423}];
const trees=[
  [65,90,1.05],[120,300,.85],[280,82,.85],[340,120,.72],[590,86,1.0],[775,110,1.1],[820,290,.8],[720,390,1.1],[630,520,.9],[390,530,1.1],[180,470,1.0],[70,575,.85],[845,540,.95],[315,390,.7],[570,470,.75],[95,205,.7],[760,220,.75],[265,255,.65]
];
let seed=8731;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
function load(){try{const s=JSON.parse(localStorage.getItem(keySave)||'null');if(s){state.x=Number.isFinite(s.x)?s.x:state.x;state.y=Number.isFinite(s.y)?s.y:state.y;state.petals=Array.isArray(s.petals)?s.petals:[];state.wellDone=!!s.wellDone}}catch{}try{const saved=JSON.parse(localStorage.getItem(roadmapSave)||'null');stepData=Array.isArray(saved)&&saved.length===4?saved:structuredClone(defaultSteps)}catch{stepData=structuredClone(defaultSteps)}}
function save(){try{localStorage.setItem(keySave,JSON.stringify({x:state.x,y:state.y,petals:state.petals,wellDone:state.wellDone}))}catch{}}
function saveRoadmap(){try{localStorage.setItem(roadmapSave,JSON.stringify(stepData))}catch{}}
function drawGrass(){seed=8731;for(let y=0;y<MAP_H;y++)for(let x=0;x<MAP_W;x++){let r=rand(),px=x*T,py=y*T;ctx.fillStyle=r>.83?'#719b56':r>.55?'#6c9652':r>.22?'#709953':'#759d58';ctx.fillRect(px,py,T,T);if(r>.48){ctx.fillStyle=r>.72?'#83aa63':'#628b4b';ctx.fillRect(px+Math.floor(rand()*17)+1,py+Math.floor(rand()*16)+2,2,2)}if(r<.12){ctx.fillStyle='#92ad65';ctx.fillRect(px+4,py+14,1,3);ctx.fillRect(px+6,py+12,1,5)}}
  // Soft, broken paths make the meadow feel lived in.
  const path=(x,y,w,h)=>{ctx.fillStyle='#b8a875';ctx.fillRect(x,y,w,h);ctx.fillStyle='#c9b986';ctx.fillRect(x+2,y+2,w-4,h-4);for(let i=0;i<Math.floor(w*h/210);i++){ctx.fillStyle=i%2?'#9e9266':'#d3c28e';ctx.fillRect(x+3+rand()*(w-6),y+3+rand()*(h-6),2,1)}};
  path(418,255,37,160);path(421,255,165,30);path(585,163,26,125);path(585,164,104,27);path(451,378,164,23);
  // Pond, with layered banks and glints.
  ctx.fillStyle='#786f4b';ctx.beginPath();ctx.ellipse(194,192,99,70,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b9aa70';ctx.beginPath();ctx.ellipse(194,189,92,64,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#57908a';ctx.beginPath();ctx.ellipse(194,184,81,53,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#66a39a';ctx.beginPath();ctx.ellipse(194,181,70,44,0,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#a5c2a0';[[160,164,12,2],[218,183,16,2],[176,201,9,2],[231,169,7,2]].forEach(a=>ctx.fillRect(...a));
  // A stepping-stone crossing at the pond's lower edge.
  [[146,233],[165,239],[185,242],[205,240],[225,234]].forEach(([x,y],i)=>{ctx.fillStyle='#877f62';ctx.fillRect(x,y,13,7);ctx.fillStyle=i%2?'#c2b58a':'#d3c49a';ctx.fillRect(x+1,y+1,10,3)});
}
function flower(x,y,color='#e7d8f1'){ctx.fillStyle='#4b713f';ctx.fillRect(x-1,y+2,2,6);ctx.fillRect(x-4,y+6,3,2);ctx.fillStyle=color;ctx.fillRect(x-3,y-2,3,3);ctx.fillRect(x+1,y-2,3,3);ctx.fillRect(x-1,y-4,3,3);ctx.fillRect(x-1,y+1,3,3);ctx.fillStyle='#f0d47a';ctx.fillRect(x,y-1,2,2)}
function drawPlants(){seed=992;for(let i=0;i<125;i++){let x=rand()*MW,y=rand()*MH;if((x>370&&x<485&&y>245&&y<430)||(x>100&&x<290&&y>115&&y<265))continue;let r=rand();if(r<.46){ctx.fillStyle=r<.2?'#d9c982':'#abc776';ctx.fillRect(x|0,y|0,2,2);ctx.fillRect((x+2)|0,(y-2)|0,2,2)}else if(r<.73){ctx.fillStyle='#71934e';ctx.fillRect(x|0,y|0,1,4);ctx.fillRect((x+2)|0,(y-2)|0,1,5)}else flower(x|0,y|0,r<.82?'#e6d9ba':'#d9c9e8')}
  for(let i=0;i<flowers.length;i++)if(!state.petals.includes(i))flower(flowers[i].x,flowers[i].y,'#e7d9f6');
}
function drawTree(x,y,s=1){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#554b37';ctx.fillRect(-4,-2,9,15);ctx.fillStyle='#3d643b';ctx.fillRect(-13,-12,26,14);ctx.fillRect(-10,-19,20,10);ctx.fillRect(-7,-24,14,7);ctx.fillStyle='#4d7843';ctx.fillRect(-10,-15,20,12);ctx.fillRect(-7,-21,14,8);ctx.fillStyle='#729451';ctx.fillRect(-7,-18,8,2);ctx.fillRect(2,-13,5,2);ctx.fillStyle='#789756';ctx.fillRect(-3,-24,4,2);ctx.fillStyle='#2e5437';ctx.fillRect(-14,-9,4,7);ctx.fillRect(10,-10,5,7);ctx.fillStyle='#6c563b';ctx.fillRect(-2,2,3,7);ctx.restore()}
function drawHouse(){// tiny cottage tucked into the east meadow
  ctx.fillStyle='#6d5e43';ctx.fillRect(662,172,78,55);ctx.fillStyle='#d3b889';ctx.fillRect(669,185,64,39);ctx.fillStyle='#c9a977';ctx.fillRect(674,190,53,32);ctx.fillStyle='#704e3b';ctx.fillRect(685,200,13,24);ctx.fillStyle='#ead59e';ctx.fillRect(688,203,7,11);ctx.fillStyle='#65918a';ctx.fillRect(706,195,11,10);ctx.fillStyle='#efe0b3';ctx.fillRect(708,197,7,6);ctx.fillStyle='#604b39';ctx.fillRect(653,168,96,12);ctx.fillRect(663,158,76,11);ctx.fillRect(674,150,55,10);ctx.fillStyle='#9a6748';ctx.fillRect(659,166,83,4);ctx.fillStyle='#92705a';ctx.fillRect(714,153,9,21);ctx.fillStyle='#b87956';ctx.fillRect(716,154,5,16);ctx.fillStyle='#927d52';ctx.fillRect(664,226,76,3);
}
function drawWell(){ctx.fillStyle='#4c6842';ctx.fillRect(445,251,29,25);ctx.fillStyle='#756f58';ctx.fillRect(447,250,27,19);ctx.fillStyle='#a49b79';ctx.fillRect(450,252,21,14);ctx.fillStyle='#536d58';ctx.fillRect(452,254,17,10);ctx.fillStyle='#83a8a0';ctx.fillRect(454,257,12,5);ctx.fillStyle='#c6bc99';ctx.fillRect(444,248,32,5);ctx.fillRect(444,248,4,22);ctx.fillRect(472,248,4,22);ctx.fillStyle='#735b43';ctx.fillRect(446,242,3,9);ctx.fillRect(471,242,3,9);ctx.fillRect(445,241,30,3);ctx.fillStyle='#a88858';ctx.fillRect(457,242,3,3);}
function drawPerson(x,y){ctx.fillStyle='#354a37';ctx.fillRect(x-7,y+6,14,3);ctx.fillStyle='#e3b784';ctx.fillRect(x-4,y-8,8,8);ctx.fillStyle='#473d32';ctx.fillRect(x-5,y-10,10,4);ctx.fillRect(x-5,y-6,2,3);ctx.fillStyle='#725b46';ctx.fillRect(x-4,y-1,8,2);ctx.fillStyle='#758b58';ctx.fillRect(x-6,y,12,8);ctx.fillStyle='#d7bd77';ctx.fillRect(x-1,y+1,2,6);ctx.fillStyle='#584839';ctx.fillRect(x-5,y+8,4,3);ctx.fillRect(x+2,y+8,4,3)}
function drawHero(){const x=Math.round(state.x),y=Math.round(state.y),step=Math.sin(walkPhase)*2,legs=Math.abs(step);ctx.fillStyle='#3d5337';ctx.fillRect(x-7,y+6,14,4);ctx.fillStyle='#54613d';ctx.fillRect(x-5,y+7,10,2);
  // boots and legs
  ctx.fillStyle='#574637';if(keys.size){ctx.fillRect(x-4,y+11+legs,3,4);ctx.fillRect(x+1,y+11-leg,3,4)}else ctx.fillRect(x-4,y+11,3,4),ctx.fillRect(x+1,y+11,3,4);
  ctx.fillStyle='#d5bc79';ctx.fillRect(x-5,y+8,10,5);ctx.fillStyle='#e0c989';ctx.fillRect(x-5,y+8,10,2);ctx.fillStyle='#557d50';ctx.fillRect(x-6,y,12,9);ctx.fillStyle='#70975c';ctx.fillRect(x-4,y+1,8,6);ctx.fillStyle='#c5aa6d';ctx.fillRect(x-6,y+7,12,2);
  ctx.fillStyle='#e8bd92';ctx.fillRect(x-4,y-8,8,8);ctx.fillStyle='#efcba1';ctx.fillRect(x-3,y-7,6,6);ctx.fillStyle='#604631';ctx.fillRect(x-5,y-10,10,4);ctx.fillRect(x-4,y-7,8,2);ctx.fillStyle='#75543b';ctx.fillRect(x-6,y-8,2,5);ctx.fillRect(x+4,y-8,2,5);
  ctx.fillStyle='#3c392e';if(state.face==='down'){ctx.fillRect(x-3,y-4,1,2);ctx.fillRect(x+2,y-4,1,2)}else if(state.face==='up'){ctx.fillStyle='#503e30';ctx.fillRect(x-5,y-8,10,2)}else{ctx.fillRect(state.face==='left'?x-4:x+2,y-4,2,2)}
  ctx.fillStyle='#6b5138';ctx.fillRect(x+5,y+2,2,5);ctx.fillStyle='#d4bd7d';ctx.fillRect(x+5,y+2,2,2);
}

