function drawWorld(now){const camX=Math.max(0,Math.min(MW-W,state.x-W/2)),camY=Math.max(0,Math.min(MH-H,state.y-H/2));ctx.clearRect(0,0,W,H);ctx.save();ctx.translate(-Math.floor(camX),-Math.floor(camY));drawGrass();drawPlants();
  // Scattered pebble clusters and tiny clover patches.
  seed=274;for(let i=0;i<60;i++){let x=rand()*MW,y=rand()*MH;if(x<100||y<90)continue;ctx.fillStyle=i%2?'#9d986f':'#b0a77b';ctx.fillRect(x|0,y|0,3,2);ctx.fillStyle='#d0c595';ctx.fillRect((x+1)|0,(y-1)|0,2,1)}
  drawHouse();drawWell();
  // Helpful little signpost at the meadow's entry.
  ctx.fillStyle='#654b32';ctx.fillRect(337,377,3,14);ctx.fillStyle='#b79860';ctx.fillRect(328,373,21,7);ctx.fillStyle='#ddc68c';ctx.fillRect(329,374,19,4);
  for(const [x,y,s] of trees)drawTree(x,y,s);
  // A companion tending the flowers.
  drawPerson(514,359);ctx.fillStyle='#f0dfa9';ctx.font='7px monospace';ctx.textAlign='center';ctx.fillText('MIRA',514,344);
  drawHero();
  // A gentle floating glimmer marks the quest flowers.
  for(let i=0;i<flowers.length;i++)if(!state.petals.includes(i)){const f=flowers[i],blink=(Math.sin(now/260+i*2)+1)/2;ctx.fillStyle=`rgba(255,244,187,${.35+blink*.35})`;ctx.fillRect(f.x-5,f.y-9,1,1);ctx.fillRect(f.x+6,f.y-5,1,1);ctx.fillStyle='#fff4c2';ctx.fillRect(f.x+5,f.y-10,1,1)}
  if(state.wellDone){ctx.fillStyle='#f4dd8e';ctx.fillRect(455,252,4,3);ctx.fillRect(462,255,3,2);ctx.fillRect(458,260,3,2)}
  ctx.restore();return {camX,camY};
}
function solid(x,y){if(x<12||y<12||x>MW-12||y>MH-12)return true;const pond=((x-194)/89)**2+((y-184)/62)**2<1; if(pond)return true;if(x>653&&x<750&&y>153&&y<230)return true;if(x>441&&x<478&&y>240&&y<279)return true;for(const [tx,ty,s] of trees){if(Math.abs(x-tx)<13*s&&Math.abs(y-(ty+1))<10*s)return true}return Math.hypot(x-514,y-359)<12;}
function showToast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');toastTimer=2.6}
function refreshQuest(){const n=state.petals.length;document.getElementById('petal-count').textContent=`${n} / 3`;document.getElementById('petal-meter').style.width=`${n/3*100}%`;document.getElementById('objective-text').textContent=state.wellDone?'The well is blooming again — thank you!':n===3?'Return to the old well and press E':'Gather moonpetals for the old well';}
function interact(){let best=-1,dist=Infinity;flowers.forEach((f,i)=>{if(!state.petals.includes(i)){const d=Math.hypot(state.x-f.x,state.y-f.y);if(d<dist){dist=d;best=i}}});if(best>=0&&dist<31){state.petals.push(best);save();refreshQuest();showToast(state.petals.length===3?'Three petals! Take them to the old well.':'A moonpetal tucked safely away.');return}
  const wellDist=Math.hypot(state.x-460,state.y-261);if(wellDist<40){if(state.wellDone){showToast('The well hums softly in the morning light.');return}if(state.petals.length>=3){state.wellDone=true;save();refreshQuest();showToast('The well blooms with light. A lovely beginning!');return}showToast(`The well is waiting. ${3-state.petals.length} moonpetal${state.petals.length===2?'':'s'} still to find.`);return}
  if(Math.hypot(state.x-514,state.y-359)<38){showToast(state.petals.length>=3?'Mira: The old well is just down the path!':'Mira: Look for tiny lilac flowers around the meadow.');return}showToast('The meadow is peaceful. Look for lilac flowers.');
}
function direction(){let x=0,y=0;if(keys.has('ArrowLeft')||keys.has('a'))x--;if(keys.has('ArrowRight')||keys.has('d'))x++;if(keys.has('ArrowUp')||keys.has('w'))y--;if(keys.has('ArrowDown')||keys.has('s'))y++;return {x,y}}
function update(dt){const d=direction(),moving=d.x||d.y;if(moving){const len=Math.hypot(d.x,d.y),speed=78*dt,dx=d.x/len*speed,dy=d.y/len*speed;if(d.x<0)state.face='left';if(d.x>0)state.face='right';if(d.y<0)state.face='up';if(d.y>0)state.face='down';if(!solid(state.x+dx,state.y))state.x+=dx;if(!solid(state.x,state.y+dy))state.y+=dy;walkPhase+=dt*13;state.elapsed+=dt}if(moving)save();}
function render(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);drawWorld(now);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)document.getElementById('toast').classList.remove('show')}requestAnimationFrame(render)}
const keyNames={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',w:'up',a:'left',s:'down',d:'right'};
window.addEventListener('keydown',e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;if(keyNames[key]){keys.add(key);e.preventDefault()}if((key==='e'||key===' '||key==='Enter')&&!e.repeat){e.preventDefault();interact()}});
window.addEventListener('keyup',e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;keys.delete(key)});window.addEventListener('blur',()=>keys.clear());
document.querySelectorAll('.touch-btn').forEach(btn=>{const key={up:'w',down:'s',left:'a',right:'d'}[btn.dataset.dir];const down=e=>{e.preventDefault();keys.add(key);btn.setPointerCapture?.(e.pointerId)};const up=e=>{e.preventDefault();keys.delete(key)};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('lostpointercapture',up)});document.getElementById('touch-action').addEventListener('pointerdown',e=>{e.preventDefault();interact()});
function renderRoadmap(){const list=document.getElementById('step-list');list.innerHTML='';stepData.forEach((step,i)=>{const li=document.createElement('li');li.className='step '+(i===0?'current':'');li.innerHTML=`<span class="step-num">0${i+1}</span><div class="step-copy"><div class="step-title"></div><div class="step-note"></div></div>`;li.querySelector('.step-title').textContent=step.title;li.querySelector('.step-note').textContent=step.note;list.append(li)})}
const modal=document.getElementById('roadmap-modal');function openEditor(){const rows=document.getElementById('edit-rows');rows.innerHTML='';stepData.forEach((step,i)=>{const row=document.createElement('div');row.className='edit-row';row.innerHTML=`<span class="step-num">0${i+1}</span><div><label>Step ${i+1} title</label><input maxlength="42" data-title="${i}"/><label style="margin-top:8px">Description</label><textarea maxlength="100" data-note="${i}"></textarea></div>`;row.querySelector('input').value=step.title;row.querySelector('textarea').value=step.note;rows.append(row)});modal.classList.add('open')}
document.getElementById('edit-steps').addEventListener('click',openEditor);document.getElementById('close-modal').addEventListener('click',()=>modal.classList.remove('open'));modal.addEventListener('pointerdown',e=>{if(e.target===modal)modal.classList.remove('open')});document.addEventListener('keydown',e=>{if(e.key==='Escape')modal.classList.remove('open')});document.getElementById('save-roadmap').addEventListener('click',()=>{stepData=stepData.map((s,i)=>({title:document.querySelector(`[data-title="${i}"]`).value.trim()||defaultSteps[i].title,note:document.querySelector(`[data-note="${i}"]`).value.trim()||defaultSteps[i].note,status:i===0?'current':'next'}));saveRoadmap();renderRoadmap();modal.classList.remove('open')});document.getElementById('reset-roadmap').addEventListener('click',()=>{stepData=structuredClone(defaultSteps);saveRoadmap();renderRoadmap();openEditor()});
load();renderRoadmap();refreshQuest();requestAnimationFrame(render);

